#include <vector>
#include <iostream>

class Resource {
public:
    Resource() = default;
    // Must be copyable and assignable for basic vector use
    Resource(const Resource&) = default;
    Resource& operator=(const Resource&) = default;
};

int main() {
    // Compiles because Resource meets requirements
    std::vector<Resource> v;
    v.push_back(Resource()); 

